const PUC_BASE = window.PUC_DATA;
// Cache global en memoria — se carga de Supabase al iniciar
const PUC_CACHE = { renombres:{}, auxiliares:[], loaded:false, empresaId:null };
const getPUC_ACTIVO = (empresaId)=>{
const mapa = {};
PUC_BASE.forEach(([c,n])=>{ mapa[String(c)] = n; });
// SOLO usar cache en memoria si ya cargó de Supabase para esta empresa
if(PUC_CACHE.loaded && PUC_CACHE.empresaId===empresaId){
  Object.entries(PUC_CACHE.renombres).forEach(([c,n])=>{ mapa[String(c)] = n; });
  PUC_CACHE.auxiliares.forEach(a=>{ if(a.c && a.n) mapa[String(a.c)] = a.n; });
}
// NO usar localStorage como fallback — evita mostrar datos eliminados
return Object.entries(mapa)
.filter(([c])=>String(c).length >= 4)
.sort((a,b)=>String(a[0]).localeCompare(String(b[0])));
};
// Cargar PUC de Supabase al cache global
const cargarPUCCache = async (empresaId)=>{
  try {
    const [rens, auxs] = await Promise.all([
      db.getRenombres(empresaId),
      db.getAuxiliares(empresaId)
    ]);
    PUC_CACHE.renombres = {};
    // getRenombres devuelve objeto {codigo:nombre}, no array
    if (Array.isArray(rens)) {
      rens.forEach(r=>{ if(r.codigo&&r.nombre) PUC_CACHE.renombres[String(r.codigo)] = r.nombre; });
    } else if (rens && typeof rens==='object') {
      Object.assign(PUC_CACHE.renombres, rens);
    }
    PUC_CACHE.auxiliares = (auxs||[]).map(a=>({c:String(a.c||a.codigo),n:a.n||a.nombre}));
    PUC_CACHE.loaded = true;
    PUC_CACHE.empresaId = empresaId;
    // Limpiar localStorage para que no queden datos viejos
    localStorage.removeItem('cf_puc_rename_'+empresaId);
    localStorage.removeItem('cf_aux_cache_'+empresaId);
    console.log('✓ PUC cache Supabase→memoria:', Object.keys(PUC_CACHE.renombres).length+' renombres,', PUC_CACHE.auxiliares.length+' auxiliares');
  } catch(e) { console.error('Error cargando PUC cache:', e); }
};
function detectarNivelPUC(codigo) {
codigo = String(codigo).trim();
if (codigo.length === 1) return "Clase";
if (codigo.length === 2) return "Grupo";
if (codigo.length === 4) return "Cuenta";
if (codigo.length === 6) return "Subcuenta";
if (codigo.length === 8) return "Auxiliar";
return "No definido";
}
function obtenerPadrePUC(codigo) {
codigo = String(codigo).trim();
if (codigo.length === 1) return "";
if (codigo.length === 2) return codigo.substring(0, 1);
if (codigo.length === 4) return codigo.substring(0, 2);
if (codigo.length === 6) return codigo.substring(0, 4);
if (codigo.length === 8) return codigo.substring(0, 6);
return "";
}
function permiteMovimientoPUC(codigo) {
return String(codigo).trim().length === 8;
}
function normalizarNaturalezaPUC(naturaleza) {
return Number(naturaleza) === 1 ? "Débito" : "Crédito";
}
function transformarPUCJerarquico(pucBase) {
return pucBase.map(([codigo, nombre, naturaleza])=>{
const codigoTexto = String(codigo).trim();
const nivel = detectarNivelPUC(codigoTexto);
return {
codigo:codigoTexto,nombre:nombre,nivel:nivel,codigo_padre:obtenerPadrePUC(codigoTexto),naturaleza:normalizarNaturalezaPUC(naturaleza),naturaleza_numero:Number(naturaleza),permite_movimiento:permiteMovimientoPUC(codigoTexto),c:codigoTexto,n:nombre,nat:Number(naturaleza),esAux:permiteMovimientoPUC(codigoTexto)
};
});
}
function crearAuxiliarPUC(subcuentaCodigo, nombreAuxiliar, consecutivo = 1, naturaleza = 1) {
const subcuenta = String(subcuentaCodigo).trim();
if (subcuenta.length !== 6) {
alert("El auxiliar debe crearse debajo de una subcuenta de 6 dígitos.");
return null;
}
const consecutivoTexto = String(consecutivo).padStart(2, "0");
const codigoAuxiliar = `${subcuenta}${consecutivoTexto}`;
return {
codigo:codigoAuxiliar,nombre:nombreAuxiliar,nivel:"Auxiliar",codigo_padre:subcuenta,naturaleza:normalizarNaturalezaPUC(naturaleza),naturaleza_numero:Number(naturaleza),permite_movimiento:true,c:codigoAuxiliar,n:nombreAuxiliar,nat:Number(naturaleza),esAux:true
};
}
