async saveAuxiliar(empresaId, aux) {
// Primero intentar update si ya existe, sino insert
const {data:existing} = await supabaseClient.from('puc_auxiliares')
  .select('id').eq('empresa_id',empresaId).eq('codigo',aux.c).single();
let error;
if (existing) {
  const res = await supabaseClient.from('puc_auxiliares')
    .update({nombre:aux.n,naturaleza:aux.nat||1,tarifa:aux.tarifa||0})
    .eq('empresa_id',empresaId).eq('codigo',aux.c);
  error = res.error;
  if(error) console.error('saveAuxiliar UPDATE ERROR',aux.c,JSON.stringify(error));
  else console.log('saveAuxiliar UPDATE OK',aux.c,'tarifa:',aux.tarifa);
} else {
  const res = await supabaseClient.from('puc_auxiliares')
    .insert({empresa_id:empresaId,codigo:aux.c,nombre:aux.n,naturaleza:aux.nat||1,tarifa:aux.tarifa||0});
  error = res.error;
  if(error) console.error('saveAuxiliar INSERT ERROR',aux.c,JSON.stringify(error));
  else console.log('saveAuxiliar INSERT OK',aux.c,'tarifa:',aux.tarifa);
}
return !error;
},
