    // ── PUC INPUT CELL — buscador reutilizable de cuenta con auxiliares ────────
    function PucInputCell({ empresaId, value, onChange, placeholder, style }) {
      const [q,      setQ]      = useState(value||'');
      const [open,   setOpen]   = useState(false);
      const [auxs,   setAuxs]   = useState([]);
      const [activas,setActivas]= useState({});
      const renamesMap = React.useMemo(()=>lsGet('cf_puc_rename_'+(empresaId||''),{}),[empresaId]);

      useEffect(()=>{
        if(!empresaId) return;
        Promise.all([db.getAuxiliares(empresaId), db.getPucActivas(empresaId)])
          .then(([a,p])=>{ setAuxs(a||[]); setActivas(p||{}); });
      },[empresaId]);

      useEffect(()=>{ setQ(value||''); },[value]);

      const getNom = (cod,nom) => renamesMap[String(cod)] || nom;

      const buscar = (txt) => {
        if(!txt||txt.length<1) return [];
        const qL = txt.toLowerCase();
        const auxCods = new Set(auxs.map(a=>a.c));
        const deAux = auxs.map(a=>({ cod:String(a.c), nom:getNom(a.c,a.n), tipo:'aux' }));
        const dePuc = PUC_BASE
          .filter(([c])=> activas[String(c)] && !auxCods.has(String(c)))
          .map(([c,n])=>({ cod:String(c), nom:getNom(c,n), tipo:'puc' }));
        const res = [...deAux,...dePuc].filter(c=>
          c.cod.startsWith(txt)||c.nom.toLowerCase().includes(qL)
        );
        res.sort((a,b)=>{
          const sa=a.cod===txt?0:a.cod.startsWith(txt)?1:2;
          const sb=b.cod===txt?0:b.cod.startsWith(txt)?1:2;
          return sa-sb||a.cod.localeCompare(b.cod);
        });
        return res.slice(0,14);
      };

      const res = buscar(q);
      // Sin query: muestra los 14 primeros para orientar al usuario
      const resVisible = res.length>0 ? res : (open ? [...auxs.map(a=>({cod:String(a.c),nom:getNom(a.c,a.n),tipo:'aux'})).slice(0,7)] : []);

      const sel = (c) => { setQ(c.cod); setOpen(false); if(onChange) onChange(c.cod,c.nom); };

      return (
        <div style={{position:'relative',width:'100%'}}>
          <input value={q}
            onChange={e=>{ setQ(e.target.value); setOpen(true); if(onChange) onChange(e.target.value,''); }}
            onFocus={()=>setOpen(true)} onBlur={()=>setTimeout(()=>setOpen(false),200)}
            onKeyDown={e=>{ if(e.key==='F4'){e.preventDefault();setOpen(true);setQ('');} if(e.key==='Escape') setOpen(false); }}
            placeholder={placeholder||'Cuenta (F4)'} style={{...(style||{}),fontFamily:'monospace'}}/>
          {open && resVisible.length>0 && (
            <div style={{position:'absolute',top:'100%',left:0,right:0,background:'#1a2035',border:'1px solid rgba(255,255,255,0.15)',borderRadius:8,zIndex:500,maxHeight:240,overflowY:'auto',boxShadow:'0 8px 28px rgba(0,0,0,0.6)'}}>
              {resVisible.map(c=>(
                <div key={c.cod} onMouseDown={()=>sel(c)}
                  style={{padding:'7px 12px',cursor:'pointer',borderBottom:'1px solid rgba(255,255,255,0.04)',display:'flex',justifyContent:'space-between',alignItems:'center'}}
                  onMouseEnter={e=>e.currentTarget.style.background='rgba(255,255,255,0.06)'}
                  onMouseLeave={e=>e.currentTarget.style.background='transparent'}>
                  <div>
                    <span style={{fontFamily:'monospace',color:'#e8b84b',fontWeight:600,fontSize:'0.82rem'}}>{c.cod}</span>
                    <span style={{marginLeft:10,color:'rgba(255,255,255,0.65)',fontSize:'0.78rem'}}>{c.nom}</span>
                  </div>
                  <span style={{fontSize:'0.62rem',padding:'1px 6px',borderRadius:8,background:c.tipo==='aux'?'rgba(251,146,60,0.12)':'rgba(79,142,247,0.1)',color:c.tipo==='aux'?'#fb923c':'#4f8ef7',fontWeight:600,marginLeft:8,flexShrink:0}}>{c.tipo==='aux'?'aux':'puc'}</span>
                </div>
              ))}
            </div>
          )}
          {open && q && resVisible.length===0 && q.length>=2 && (
            <div style={{position:'absolute',top:'100%',left:0,right:0,background:'#1a2035',border:'1px solid rgba(255,255,255,0.15)',borderRadius:8,zIndex:500,padding:'10px 12px',fontSize:'0.78rem',color:'rgba(255,255,255,0.35)'}}>
              Sin coincidencias — código libre permitido
            </div>
          )}
        </div>
      );
    }

