    const hayActivas=Object.keys(activas||{}).length>0;
    const pucEntries=PUC_BASE
      .filter(([c])=>{ const cs=String(c); return (!hayActivas||activas[cs]) && !auxCods.has(cs); })
      .map(([c,n])=>({cod:String(c),nom:renMap[String(c)]||n,tipo:'puc'}));
    // Auxiliares primero, luego PUC (activas si hay, todas si no hay activas)
