movs.push({ fecha:eg.fecha,tipo:'CE',numero:eg.numero,cuenta:ctaBanco,detalle:eg.concepto||'',tercero_nit:eg.nit||'',tercero_nombre:resolverNombre(eg.nit||'',eg.beneficiario||''),debito:0,credito:parseFloat(eg.valor)||0,mes:eg.fecha.slice(0,7) });
