const getNextNum = (tipo)=>{
// Calcular desde comprobantes reales — acepta formatos "CO-005", "5", "CO005"
const maxExistente = comprobantes
  .filter(c=>c.tipo_doc===tipo)
  .reduce((max,c)=>{
    const n = parseInt((c.numero||'').replace(/[^0-9]/g,''))||0;
    return Math.max(max,n);
  },0);
const fromLS = numeracion && numeracion[tipo] ? numeracion[tipo] : 1;
const siguiente = Math.max(maxExistente+1, fromLS);
return tipo+"-"+String(siguiente).padStart(3,"0");
};
