const importarDesdeIA = () => {
  const raw = localStorage.getItem('cf_ia_comprobantes');
  const ts  = localStorage.getItem('cf_ia_timestamp');
  if (!raw) { toast$('Sin comprobantes en ContaIA — genere facturas primero', false); return; }
  const mins = ts ? Math.round((Date.now()-parseInt(ts))/60000) : 999;
  if (mins > 120) { toast$('Comprobantes ContaIA de más de 2 horas — genere nuevos', false); return; }
  try {
    const comps = JSON.parse(raw);
    if (!comps||!comps.length) { toast$('Sin comprobantes', false); return; }
    const c = comps[0];
    const lineas = typeof c.detalles==='string' ? JSON.parse(c.detalles||'[]') : (c._lineas||[]);
    // Cargar en el formulario de causación
    setComp({
      ...emptyComp(),
      fecha: c.fecha||new Date().toISOString().slice(0,10),
      concepto: c.concepto||'',
      nit: c.nit||c.tercero_nit||'',
      beneficiario: c.beneficiario||c.tercero_nombre||'',
      tipo_doc: c.tipo_doc||'CO',
    });
    setFilas(lineas.length>0 ? lineas.map(l=>({
      ...emptyFila(),
      cuenta: String(l.cuenta||''),
      debito: String(parseFloat(l.debito)||0),
      credito: String(parseFloat(l.credito)||0),
      detalle: l.detalle||'',
      nit: l.tercero_nit||c.nit||''
    })) : [emptyFila(), emptyFila(), emptyFila()]);
    setTercBusqVal({});
    setShowTercBusq({});
    // Limpiar para no reimportar
    if (comps.length<=1) localStorage.removeItem('cf_ia_comprobantes');
    else localStorage.setItem('cf_ia_comprobantes', JSON.stringify(comps.slice(1)));
    toast$('✓ Comprobante ContaIA cargado'+(comps.length>1?' — quedan '+(comps.length-1)+' más':''));
  } catch(e) { toast$('Error ContaIA: '+e.message, false); }
};

