const importarExcel = async (file)=>{
if (!file) return;
toast$("⏳ Procesando Excel...");
try {
const data = await file.arrayBuffer();
const wb = XLSX.read(data);
const ws = wb.Sheets[wb.SheetNames[0]];
const rows = XLSX.utils.sheet_to_json(ws, { header:1,defval:"" });
if (rows.length < 2) { toast$("El archivo está vacío", false); return; }
const headers = rows[0].map(h=>String(h).trim().toLowerCase());
const col = (names)=>{
for (const n of names) {
const idx = headers.findIndex(h=>h.includes(n.toLowerCase()));
if (idx >= 0) return idx;
}
return -1;
};
const iDocNum = col(["docnum","doc_num","numero","n°","num"]);
const iDocFec = col(["docfec","fecha","date","fec"]);
const iTpcCod = col(["tpccod","tipo","type","tpc"]);
const iPlnCod = col(["plncod","cuenta","account","pln","plancod"]);
const iDocDet = col(["docdet","detalle","descripcion","detail","det"]);
const iTerNit = col(["ternit","nit","tercero","tercero_nit"]);
const iDocDeb = col(["docdeb","debito","debit","deb"]);
const iDocCre = col(["doccre","credito","credit","cre"]);
const iCtoCod = col(["ctocod","centrocosto","cc","cto"]);
const iDocAux = col(["docaux","aux","auxiliar"]);
if (iPlnCod === -1) { toast$("No se encontró columna de cuenta (PlnCod)", false); return; }
const grupos = {};
const ordenGrupos = [];
rows.slice(1).forEach(row=>{
const docNum = String(row[iDocNum] ?? "").trim();
if (!docNum) return;
if (!grupos[docNum]) { grupos[docNum] = []; ordenGrupos.push(docNum); }
grupos[docNum].push(row);
});
if (ordenGrupos.length === 0) { toast$("No se encontraron comprobantes", false); return; }
let creados = 0, errores = 0;
const nuevosComps = [];
for (const docNum of ordenGrupos) {
const filas = grupos[docNum];
const primeraFila = filas[0];
const fecha = String(primeraFila[iDocFec] ?? today()).trim() || today();
const tipDoc = iTpcCod >= 0 ? String(primeraFila[iTpcCod] ?? "CO").trim() : "CO";
const concepto = iDocDet >= 0 ? String(primeraFila[iDocDet] ?? "").trim() : "";
const filasComp = filas.map(row=>({
id:uid(),cuenta:iPlnCod >= 0 ? String(row[iPlnCod] ?? "").trim() : "",detalle:iDocDet >= 0 ? String(row[iDocDet] ?? "").trim() : "",documento:iDocAux >= 0 ? String(row[iDocAux] ?? "").trim() : "",tercero_nit:iTerNit >= 0 ? String(row[iTerNit] ?? "").trim() : "",tercero_nombre:"",debito:parseFloat(String(row[iDocDeb] ?? "0").replace(/[^0-9.-]/g,"")) || 0,credito:parseFloat(String(row[iDocCre] ?? "0").replace(/[^0-9.-]/g,"")) || 0,base_gravable:"",tarifa:"",
})).filter(f=>f.cuenta);
const totDeb = filasComp.reduce((s,f)=>s+f.debito,0);
const totCre = filasComp.reduce((s,f)=>s+f.credito,0);
const dif = Math.abs(totDeb - totCre);
if (dif > 1) { errores++; continue; } // No cuadra, saltar
const compData = {
id:uid(),tipo_doc:tipDoc,numero:docNum,fecha:fecha,fecha_vencimiento:"", concepto,estado:"causado",valor_bruto:totDeb,neto_pagar:totDeb,base_retefuente:0,tarifa_retefuente:0,valor_retefuente:0,cuenta_retefuente:"",base_reteiva:0,tarifa_reteiva:0,valor_reteiva:0,cuenta_reteiva:"",base_reteica:0,tarifa_reteica:0,valor_reteica:0,cuenta_reteica:"",base_iva:0,tarifa_iva:0,valor_iva:0,cuenta_iva:"",tercero_id:"",tercero_nit:filasComp[0]?.tercero_nit||"",tercero_nombre:"",detalles:JSON.stringify(filasComp)
};
const ok = await db.saveComprobante(empresaId, compData);
if (ok) { nuevosComps.push(compData); creados++; }
else errores++;
}
setComprobantes(p=>[...nuevosComps, ...p]);
if (errores > 0) {
toast$(`✓ ${creados} importados. ⚠ ${errores} con error (no cuadran o fallaron)`);
} else {
toast$(`✓ ${creados} comprobante${creados!==1?"s":""} importado${creados!==1?"s":""} exitosamente`);
}
} catch(e) {
console.error(e);
toast$("Error al leer el archivo:"+e.message, false);
}
};
const guardar = async ()=>{
if (!comp.fecha || !comp.numero) { toast$("Complete tipo, número y fecha", false); return; }
if (filas.filter(f=>f.cuenta).length === 0) { toast$("Agregue al menos una cuenta", false); return; }
if (Math.abs(diferencia) > 0.01) { toast$("El comprobante no cuadra — diferencia:"+fmtCOP(Math.abs(diferencia)), false); return; }
const filasValidas = filas.filter(f=>f.cuenta);
const compData = {
...comp,valor_bruto:totDebito,neto_pagar:totDebito,detalles:JSON.stringify(filasValidas)
};
const ok = await db.saveComprobante(empresaId, compData);
if (!ok) { toast$("Error al guardar", false); return; }
setComprobantes(p=>[compData,...p.filter(c=>c.id!==compData.id)]);
// Avanzar consecutivo
const numActual = parseInt((compData.numero||'').replace(/[^0-9]/g,''))||1;
if (setNumeracion) {
  const newNum = {...numeracion, [compData.tipo_doc]: numActual+1};
  setNumeracion(newNum);
  lsSet('cf_numeracion_'+empresaId, newNum);
}
setModal(false);
toast$("✓ Comprobante guardado");
};
