g.movs.forEach((m,i)=>{
sal += m.debito - m.credito;
body += `<tr style="background:${i%2===0?'#fff':'#f9f7f4'}"><td style="padding:5px 8px;font-size:7.5pt;color:#555;white-space:nowrap;border-bottom:1px solid #ede8de">${m.fecha}</td><td style="padding:5px 8px;font-size:7.5pt;color:#666;border-bottom:1px solid #ede8de">${m.tipo} ${m.numero}</td><td style="padding:5px 8px;font-size:7.5pt;border-bottom:1px solid #ede8de;max-width:180px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis">${m.detalle}</td><td style="padding:5px 8px;font-size:7.5pt;color:#888;border-bottom:1px solid #ede8de;white-space:nowrap">${m.tercero_nit||'—'}</td><td style="padding:5px 8px;text-align:right;font-size:7.5pt;color:#1a3160;border-bottom:1px solid #ede8de">${m.debito?fmt(m.debito):''}</td><td style="padding:5px 8px;text-align:right;font-size:7.5pt;color:#5b21b6;border-bottom:1px solid #ede8de">${m.credito?fmt(m.credito):''}</td><td style="padding:5px 8px;text-align:right;font-size:7.5pt;font-weight:600;color:${sal>=0?'#166534':'#991b1b'};border-bottom:1px solid #ede8de">${fmt(Math.abs(sal))}</td></tr>`;
});
