function generarBalancePDF(egresosLista, empData, desde, hasta) {
if (!egresosLista || !egresosLista.length) return false;
function getNombreCuenta(cod) {
const nombres = {
"1":"ACTIVO","11":"DISPONIBLE","13":"DEUDORES","14":"INVENTARIOS","15":"PROPIEDADES",
"2":"PASIVO","21":"OBLIGACIONES FINANCIERAS","22":"CUENTAS POR PAGAR","23":"ACREEDORES VARIOS","24":"IMPUESTOS POR PAGAR",
"3":"PATRIMONIO","31":"CAPITAL SOCIAL","33":"RESERVAS",
"4":"INGRESOS","41":"OPERACIONALES","42":"NO OPERACIONALES",
"5":"GASTOS","51":"GASTOS OPERACIONALES","52":"GASTOS NO OPERACIONALES",
"6":"COSTOS","61":"COSTOS DE VENTAS",
};
return nombres[cod] || ("CUENTA "+cod);
}
const jerarquia = {};
egresosLista.forEach(e=>{
const cod = e.cuenta || "";
if (!cod) return;
if (!jerarquia[cod]) jerarquia[cod] = { nombre:e.tipo,debito:0,credito:0,nivel:5,terceros: {} };
jerarquia[cod].debito += (e.valor || 0);
const nitKey = e.nit || "SIN_NIT";
if (!jerarquia[cod].terceros[nitKey]) jerarquia[cod].terceros[nitKey] = { nombre:e.beneficiario,debito:0,credito:0 };
jerarquia[cod].terceros[nitKey].debito += (e.valor || 0);
[[1,1],[2,2],[4,3],[6,4]].forEach(([len, nivel])=>{
if (cod.length > len) {
const padre = cod.substring(0, len);
if (!jerarquia[padre]) jerarquia[padre] = { nombre:getNombreCuenta(padre),debito:0,credito:0, nivel,terceros: {} };
jerarquia[padre].debito += (e.valor || 0);
}
});
});
const sorted = Object.entries(jerarquia).sort((a,b)=>a[0].localeCompare(b[0]));
let totD = 0, totC = 0, filas = "";
sorted.filter(([c])=>c.length === 1).forEach(([,d])=>{ totD += d.debito; totC += d.credito; });
sorted.forEach(([cod, data])=>{
const nivel = data.nivel || 5;
const clase = cod[0] || "5";
const esAcreedor = ["2","3","4"].includes(clase);
const saldo = esAcreedor ? data.credito - data.debito : data.debito - data.credito;
const saldoStr = "$" + Math.abs(saldo).toLocaleString("es-CO");
const saldoDisplay = saldo < 0 ? "("+saldoStr+")" : saldoStr;
const indent = ["","","&nbsp;&nbsp;","&nbsp;&nbsp;&nbsp;&nbsp;","&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;","&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;"][nivel] || "";
const bgColors = ["","#e8f0fe","#eef2ff","#f5f7ff","#ffffff","#ffffff"];
const bg = bgColors[nivel] || "#fff";
const fontW = nivel <= 3 ? "700" : nivel === 4 ? "600" : "400";
const fontSize = nivel <= 2 ? "8.5pt" : "8pt";
const codColor = nivel <= 4 ? "#1a3160" : "#555";
const nomColor = nivel <= 3 ? "#0f1f3d" : "#333";
const saldoColor = saldo < 0 ? "#991b1b" : saldo > 0 ? "#166534" : "#555";
filas += `<tr style="background:${bg}">
<td style="padding:5px 8px;font-family:monospace;font-size:${fontSize};font-weight:${fontW};color:${codColor};border-bottom:1px solid #ede8de;white-space:nowrap">${cod}</td>
<td style="padding:5px 8px;font-size:${fontSize};font-weight:${fontW};color:${nomColor};border-bottom:1px solid #ede8de">${indent}${data.nombre}</td>
<td style="padding:5px 8px;text-align:right;font-size:${fontSize};color:#888;border-bottom:1px solid #ede8de">0.00</td>
<td style="padding:5px 8px;text-align:right;font-size:${fontSize};font-weight:${fontW};color:#1a3160;border-bottom:1px solid #ede8de">${data.debito ? "$"+data.debito.toLocaleString("es-CO") : "0.00"}</td>
<td style="padding:5px 8px;text-align:right;font-size:${fontSize};font-weight:${fontW};color:#5b21b6;border-bottom:1px solid #ede8de">${data.credito ? "$"+data.credito.toLocaleString("es-CO") : "0.00"}</td>
<td style="padding:5px 8px;text-align:right;font-size:${fontSize};font-weight:${fontW};color:${saldoColor};border-bottom:1px solid #ede8de">${saldoDisplay}</td>
</tr>`;
if (nivel >= 5 && data.terceros) {
Object.entries(data.terceros).forEach(([nit, t])=>{
const tSaldo = esAcreedor ? t.credito - t.debito : t.debito - t.credito;
const tStr = "$" + Math.abs(tSaldo).toLocaleString("es-CO");
const tDisplay = tSaldo < 0 ? "("+tStr+")" : tStr;
const tColor = tSaldo < 0 ? "#991b1b" : tSaldo > 0 ? "#166534" : "#555";
filas += `<tr style="background:#fdfcf8">
<td style="padding:4px 8px;font-size:7.5pt;color:#888;border-bottom:1px solid #f0ebe0;font-style:italic">${nit==="SIN_NIT"?"—":nit}</td>
<td style="padding:4px 8px;font-size:7.5pt;color:#666;border-bottom:1px solid #f0ebe0;font-style:italic">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;${t.nombre}</td>
<td style="padding:4px 8px;text-align:right;font-size:7.5pt;color:#aaa;border-bottom:1px solid #f0ebe0">0.00</td>
<td style="padding:4px 8px;text-align:right;font-size:7.5pt;color:#1a3160;border-bottom:1px solid #f0ebe0">${t.debito ? "$"+t.debito.toLocaleString("es-CO") : "0.00"}</td>
<td style="padding:4px 8px;text-align:right;font-size:7.5pt;color:#5b21b6;border-bottom:1px solid #f0ebe0">${t.credito ? "$"+t.credito.toLocaleString("es-CO") : "0.00"}</td>
<td style="padding:4px 8px;text-align:right;font-size:7.5pt;color:${tColor};border-bottom:1px solid #f0ebe0">${tDisplay}</td>
</tr>`;
});
}
});
const logoHtml = empData && empData.logo
? `<div style="background:rgba(255,255,255,0.95);border-radius:10px;padding:6px 14px;display:inline-flex;align-items:center"><img src="${empData.logo}" style="height:52px;object-fit:contain"/></div>`
: `<div style="width:52px;height:52px;background:rgba(255,255,255,0.15);border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:1.8rem">🏢</div>`;
const fD = f=>{ if(!f)return"—"; const[y,m,d]=f.split("-"); return d+"/"+m+"/"+y; };
const periodoTexto = desde && hasta ? fD(desde)+" al "+fD(hasta) : "Todos los períodos";
const empNombre = (empData && empData.nombre) || "Empresa";
const empNit = (empData && empData.nit) || "—";
const empCiudad = (empData && empData.ciudad) || "";
const empTel = (empData && empData.telefono) ? "· Tel:"+empData.telefono : "";
const w = window.open("","_blank");
if (!w) { alert("Por favor permite las ventanas emergentes para generar el PDF."); return false; }
w.document.write(`<!DOCTYPE html><html><head><meta charset="UTF-8">
<title>Balance de Prueba - ${empNombre}</title>
<style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:Arial,sans-serif;padding:20px;color:#0f1f3d;font-size:8pt;-webkit-print-color-adjust:exact;print-color-adjust:exact}.page{max-width:780px;margin:0 auto;border:2px solid #0f1f3d;border-radius:8px;overflow:hidden}.hdr{padding:12px 22px;display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #0f1f3d}.hdr img{height:48px;object-fit:contain}.emp h1{font-size:12pt;font-weight:700;color:#0f1f3d;margin-bottom:2px}.emp p{font-size:7.5pt;color:#666}.bar{background:#0f1f3d;padding:8px 22px;display:flex;justify-content:space-between;align-items:center;-webkit-print-color-adjust:exact;print-color-adjust:exact}.bar h2{color:#c9a84c;font-size:9pt;text-transform:uppercase;letter-spacing:1.5px}.bar span{color:rgba(255,255,255,0.7);font-size:7.5pt}table{width:100%;border-collapse:collapse;font-size:8pt}thead tr{background:#0f1f3d;-webkit-print-color-adjust:exact;print-color-adjust:exact}thead th{padding:8px;color:#fff;font-weight:700;font-size:7pt;text-transform:uppercase;border:1px solid #0f1f3d}thead th:nth-child(n+3){text-align:right}.tot-row td{background:#0f1f3d;padding:10px 8px;font-weight:700;color:#c9a84c;-webkit-print-color-adjust:exact;print-color-adjust:exact}tbody tr:nth-child(even){background:#f4f6fa}tbody td{padding:5px 8px;border-bottom:1px solid #ddd}.foot{padding:10px 22px;display:flex;justify-content:space-between;align-items:center;border-top:1.5px solid #0f1f3d;font-size:7pt;color:#666}.firma{text-align:center}.linea{border-top:1.5px solid #0f1f3d;padding-top:36px;margin-bottom:4px;width:170px;margin-left:auto}.fn{font-size:7pt;color:#0f1f3d;font-weight:700;text-transform:uppercase}.fc{font-size:6pt;color:#aaa}@media print{body{padding:0}.page{border-radius:0}}</style></head><body>
<div class="page">
<div class="hdr">${logoHtml}<div class="emp"><h1>${empNombre}</h1><p>NIT: ${empNit} · ${empCiudad} ${empTel}</p></div></div>
<div class="bar"><h2>Balance de Prueba</h2><span>${periodoTexto}</span></div>
<table>
<thead><tr>
<th style="text-align:left;width:90px">Código</th>
<th style="text-align:left">Nombre</th>
<th style="width:80px">Sld. Anterior</th>
<th style="width:90px">Débito</th>
<th style="width:90px">Crédito</th>
<th style="width:90px">Saldo</th>
</tr></thead>
<tbody>${filas}</tbody>
<tfoot><tr class="tot-row">
<td colspan="2">Totales</td>
<td style="text-align:right">$ 0.00</td>
<td style="text-align:right">$${totD.toLocaleString("es-CO")}</td>
<td style="text-align:right">$${totC.toLocaleString("es-CO")}</td>
<td style="text-align:right">$${Math.abs(totD-totC).toLocaleString("es-CO")}</td>
</tr></tfoot>
</table>
<div class="foot"><div>Generado: ${new Date().toLocaleString("es-CO")} — ContaFlex · Sistema Contable</div>
<div class="firma"><div class="linea"></div><div class="fn">Contador / Revisor</div><div class="fc">Nombre · Firma · Tarjeta Profesional</div></div>
</div></div></body></html>`);
w.document.close();
setTimeout(()=>{ w.focus(); w.print(); }, 800);
return true;
}
