// ── Autocomplete de entidades de seguridad social ──────────────────────
function SSAutocomplete({ label, tipo, value, onChange, empresaId, toast$ }) {
const [q, setQ] = React.useState(value||'');
const [opts, setOpts] = React.useState([]);
const [show, setShow] = React.useState(false);
const [loading, setLoading] = React.useState(false);
const timer = React.useRef(null);
React.useEffect(()=>{ setQ(value||''); },[value]);
const buscar = (texto) => {
clearTimeout(timer.current);
if (!texto || texto.length < 2) { setOpts([]); setShow(false); return; }
setLoading(true);
timer.current = setTimeout(async ()=>{
const res = await db.buscarEntidadSS(texto, tipo);
setOpts(res); setShow(res.length>0); setLoading(false);
}, 300);
};
const seleccionar = async (ent) => {
setQ(ent.nombre); setShow(false);
onChange(ent.nombre, ent);
// Crear/verificar tercero en background
if (empresaId) db.ensureTerceroSS(empresaId, ent).catch(()=>{});
};
const inpSt = {padding:'8px 12px',border:'1px solid rgba(255,255,255,0.1)',borderRadius:8,fontFamily:'inherit',fontSize:'0.83rem',outline:'none',width:'100%',background:'rgba(255,255,255,0.06)',color:'var(--text)',boxSizing:'border-box'};
return (
<div style={{position:'relative'}}>
<label style={{fontSize:'0.7rem',fontWeight:700,textTransform:'uppercase',color:'#e8eaf0',marginBottom:5,display:'block'}}>{label}</label>
<div style={{position:'relative'}}>
<input value={q} onChange={e=>{setQ(e.target.value);buscar(e.target.value);onChange(e.target.value,null);}}
onFocus={()=>{ if(q&&q.length>=2) buscar(q); }}
onBlur={()=>setTimeout(()=>setShow(false),200)}
placeholder={`Buscar ${label}...`} style={inpSt}/>
{loading && <span style={{position:'absolute',right:8,top:'50%',transform:'translateY(-50%)',fontSize:'0.7rem',color:'#c9a84c'}}>⏳</span>}
</div>
{show && opts.length>0 && (
<div style={{position:'absolute',top:'100%',left:0,right:0,background:'#0f1f3d',border:'1px solid rgba(201,168,76,0.4)',borderRadius:8,zIndex:999,maxHeight:220,overflowY:'auto',boxShadow:'0 8px 24px rgba(0,0,0,0.5)'}}>
{opts.map(ent=>(
<div key={ent.id} onMouseDown={()=>seleccionar(ent)}
style={{padding:'8px 12px',cursor:'pointer',borderBottom:'1px solid rgba(255,255,255,0.05)',transition:'background 0.15s'}}
onMouseEnter={e=>e.currentTarget.style.background='rgba(201,168,76,0.15)'}
onMouseLeave={e=>e.currentTarget.style.background='transparent'}>
<div style={{fontSize:'0.83rem',fontWeight:600,color:'#fff'}}>{ent.nombre}</div>
<div style={{fontSize:'0.72rem',color:'rgba(255,255,255,0.45)',marginTop:2}}>
NIT: {ent.nit} {ent.codigo_pila?`· PILA: ${ent.codigo_pila}`:''} {ent.regimen?`· ${ent.regimen}`:''}
</div>
</div>
))}
</div>
)}
</div>
);
}
