<div><div style={{fontSize:"0.65rem",color:"rgba(255,255,255,0.5)",textTransform:"uppercase"}}>Ítems</div><div style={{color:"#fff",fontWeight:700}}>{filas.filter(f=>f.cuenta).length}</div></div>
