{busqueda&&<button onClick={()=>setBusqueda("")} style={{background:"#1e2538",border:"none",borderRadius:6,padding:"6px 10px",cursor:"pointer",color:"var(--text2)",fontSize:"0.78rem"}}>✕</button>}
