{ctas.tipo==="61"&&<div style={{background:"#fef9c3",padding:"10px 24px",borderBottom:"1px solid #fde68a",fontSize:"0.8rem",color:"#854d0e"}}>⚠️ Modo <strong>Consorcio / Obra</strong> — todas las cuentas de nómina se contabilizan en la clase 6 (Costos)</div>}
