                    <td style={{padding:'9px 8px', textAlign:'right', fontFamily:'serif'}}>{numFmt((g.patrimonio?.cuentas||[]).filter(c=>String(c.c).startsWith('36')||String(c.c).startsWith('37')).reduce((s,c)=>s+c.saldo,0))}</td>
