const importarExtracto = async (file) => {
  setImportando(true);
  try {
    const text = await file.text();
    const lines = text.split('\n');
    const movs = [];
    // Detectar formato CSV Banco de Bogotá
    // Formato: Fecha;CodTrans;Descripcion;Ciudad;Oficina;Documento;Valor;Saldo
    lines.forEach((line, i) => {
      if(i === 0) return; // saltar encabezado
      const cols = line.split(';').map(c => c.trim().replace(/"/g,''));
      if(cols.length < 6) return;
      const fecha = cols[0];
      const desc = cols[2] || cols[1] || '';
      const doc = cols[5] || '';
      const valorStr = (cols[6] || '0').replace(/\./g,'').replace(',','.');
      const saldoStr = (cols[7] || '0').replace(/\./g,'').replace(',','.');
      const valor = parseFloat(valorStr) || 0;
      const saldo = parseFloat(saldoStr) || 0;
      if(!fecha || !valor) return;
      // Convertir fecha DD/MM a 2026-MM-DD
      const partes = fecha.split('/');
      const fechaISO = partes.length === 2 
        ? '2026-'+partes[1].padStart(2,'0')+'-'+partes[0].padStart(2,'0')
        : fecha;
      movs.push({
        id: Math.random().toString(36).slice(2),
        fecha: fechaISO,
        descripcion: desc,
        referencia: doc,
        debito: valor < 0 ? Math.abs(valor) : 0,
        credito: valor > 0 ? valor : 0,
        saldo: saldo
      });
    });
    if(movs.length > 0) {
      setMovBanco(movs);
      toast$('✓ '+movs.length+' movimientos importados del extracto');
    } else {
      toast$('No se encontraron movimientos. Verifique el formato CSV', false);
    }
  } catch(e) {
    toast$('Error al leer el archivo: '+e.message, false);
  }
  setImportando(false);
};
