const [conciliados, setConciliados] = React.useState([]);
const [pendientesBanco, setPendientesBanco] = React.useState([]);
const [pendientesContab, setPendientesContab] = React.useState([]);
const [diferencias, setDiferencias] = React.useState([]);
const [historial, setHistorial] = React.useState([]);
const [ejecutado, setEjecutado] = React.useState(false);
const [modalManual, setModalManual] = React.useState(null);
const [selContab, setSelContab] = React.useState([]);
const [busqManual, setBusqManual] = React.useState('');
const ejecutarConciliacion = ()=>{
const conc = [], pBanco = [], pContab = [...movContab], dif = [];
const usados = new Set();
movBanco.forEach(mb=>{
const valor = mb.credito || mb.debito;
const idx = pContab.findIndex(mc=>{
if(usados.has(mc.id)) return false;
const vC = mc.credito || mc.debito;
return Math.abs(vC - valor) < 1 && mc.fecha === mb.fecha;
});
if(idx >= 0) {
usados.add(pContab[idx].id);
conc.push({banco:mb,contab:pContab[idx],estado:'conciliado',dif:0});
} else {
const idxVal = pContab.findIndex(mc=>{
if(usados.has(mc.id)) return false;
const vC = mc.credito || mc.debito;
return Math.abs(vC - valor) < 1;
});
if(idxVal >= 0) {
usados.add(pContab[idxVal].id);
conc.push({banco:mb,contab:pContab[idxVal],estado:'posible',dif:0});
} else {
pBanco.push(mb);
}
}
});
const restContab = pContab.filter(mc=>!usados.has(mc.id));
setConciliados(conc);
setPendientesBanco(pBanco);
setPendientesContab(restContab);
setDiferencias(pBanco.filter(b=>(b.debito||b.credito) > 0 && (b.descripcion.toLowerCase().includes('comis') || b.descripcion.toLowerCase().includes('gmf'))));
setEjecutado(true);
setVista('tabla');
if(toast$) toast$('✓ Conciliación ejecutada correctamente');
};
const confirmarManual = ()=>{
if(!modalManual || selContab.length === 0) return;
const nuevos = [...conciliados, {banco:modalManual,contab:selContab[0],estado:'manual',dif:0}];
setConciliados(nuevos);
setPendientesBanco(prev=>prev.filter(b=>b.id !== modalManual.id));
setPendientesContab(prev=>prev.filter(c=>!selContab.find(s=>s.id === c.id)));
setModalManual(null); setSelContab([]);
if(toast$) toast$('✓ Conciliación manual registrada');
};
const guardar = ()=>{
const reg = {id:uid(), banco, cuenta, periodo,fecha:today(),usuario:session.usuario||'admin',estado:'guardada',conciliados:conciliados.length,pendBanco:pendientesBanco.length,pendContab:pendientesContab.length};
setHistorial(h=>[reg,...h]);
if(toast$) toast$('✓ Conciliación guardada en historial');
};
const generarNB = async () => {
// Tomar movimientos bancarios sin conciliar que sean gastos (comisiones, IVA, GMF)
const gastos = pendientesBanco.filter(b=>b.debito>0);
if(!gastos.length){if(toast$)toast$('No hay gastos bancarios pendientes de contabilizar',false);return;}
const compsAll = await db.getComprobantes(session.empresaId);
const maxNB = compsAll.filter(c=>c.tipo_doc==='NB').reduce((max,c)=>{
  const n=parseInt((c.numero||'').replace(/\D/g,''))||0;return n>max?n:max;
},0);
const numNB = 'NB-'+String(maxNB+1).padStart(4,'0');
const numActual = lsGet('cf_numeracion_'+session.empresaId,{NB:1});
// Construir lineas — debito gasto bancario, credito banco
const lineas = [];
const ctas = {...CUENTAS_NOM_DEFAULT,...lsGet('nom_cuentas',{})};
gastos.forEach(g=>{
  const desc = g.descripcion||'';
  const cfg = concConfig || DEFAULT_CONFIG;
  let ctaDeb = cfg.cta_otras||'530595';
  if(desc.toLowerCase().includes('gmf')||desc.toLowerCase().includes('4x1000')) ctaDeb = cfg.cta_gmf||'530520';
  else if(desc.toLowerCase().includes('iva')) ctaDeb = cfg.cta_iva_bancario||'240810';
  else if(desc.toLowerCase().includes('comis')) ctaDeb = cfg.cta_comisiones||'530515';
  else if(desc.toLowerCase().includes('interes')) ctaDeb = cfg.cta_intereses||'530510';
  lineas.push({id:uid(),cuenta:ctaDeb,detalle:g.descripcion,documento:numNB,tercero_nit:'',tercero_nombre:'Banco de Bogotá',debito:String(Math.round(g.debito)),credito:''});
});
const totalNB = gastos.reduce((s,g)=>s+g.debito,0);
// Cuenta banco PUC
const ctaBanco = (concConfig&&concConfig.cuenta_puc)||banco||'111005';
lineas.push({id:uid(),cuenta:ctaBanco,detalle:'Gastos bancarios '+periodo,documento:numNB,tercero_nit:'',tercero_nombre:'',debito:'',credito:String(Math.round(totalNB))});
const comp = {
  id:uid(),tipo_doc:'NB',numero:numNB,fecha:today(),fecha_vencimiento:'',
  concepto:'Gastos bancarios '+periodo+' — '+banco,estado:'causado',
  valor_bruto:totalNB,neto_pagar:totalNB,
  base_retefuente:0,tarifa_retefuente:0,valor_retefuente:0,cuenta_retefuente:'',
  base_reteiva:0,tarifa_reteiva:0,valor_reteiva:0,cuenta_reteiva:'',
  base_reteica:0,tarifa_reteica:0,valor_reteica:0,cuenta_reteica:'',
  base_iva:0,tarifa_iva:0,valor_iva:0,cuenta_iva:'',
  tercero_id:'',tercero_nit:'',tercero_nombre:'Banco de Bogotá',
  detalles:JSON.stringify(lineas)
};
const ok = await db.saveComprobante(session.empresaId,comp);
if(ok){
  lsSet('cf_numeracion_'+session.empresaId,{...numActual,NB:maxNB+2});
  if(toast$)toast$('✓ Nota Bancaria '+numNB+' generada — '+gastos.length+' gastos contabilizados');
}else{if(toast$)toast$('Error al guardar NB',false);}
};

const exportarExcel = () => {
if(!ejecutado){if(toast$)toast$('Ejecute la conciliación primero',false);return;}
const wb = XLSX.utils.book_new();
// Hoja conciliados
const rowsConc = [['Estado','Fecha Banco','Descripción Banco','Ref.','Débito','Crédito','Fecha Contab','Comprobante','Descripción Contab']];
conciliados.forEach(c=>{rowsConc.push([c.estado,c.banco.fecha,c.banco.descripcion,c.banco.referencia,c.banco.debito||0,c.banco.credito||0,c.contab?.fecha||'',c.contab?.comprobante||'',c.contab?.descripcion||'']);});
const ws1 = XLSX.utils.aoa_to_sheet(rowsConc);
ws1['!cols']=[10,12,35,12,14,14,12,14,30].map(w=>({wch:w}));
XLSX.utils.book_append_sheet(wb,ws1,'Conciliados');
// Hoja pendientes banco
const rowsPB = [['Fecha','Descripción','Ref.','Débito','Crédito','Saldo']];
pendientesBanco.forEach(b=>{rowsPB.push([b.fecha,b.descripcion,b.referencia,b.debito||0,b.credito||0,b.saldo||0]);});
const ws2 = XLSX.utils.aoa_to_sheet(rowsPB);
XLSX.utils.book_append_sheet(wb,ws2,'Pendientes Banco');
// Hoja resumen
const rowsRes = [['Concepto','Valor'],['Saldo inicial',parseFloat(saldoIni)||0],['Total abonos',movBanco.reduce((s,m)=>s+(m.credito||0),0)],['Total cargos',movBanco.reduce((s,m)=>s+(m.debito||0),0)],['Saldo final extracto',parseFloat(saldoFin)||0],['Movimientos conciliados',conciliados.length],['Pendientes banco',pendientesBanco.length],['Pendientes contabilidad',pendientesContab.length]];
const ws3 = XLSX.utils.aoa_to_sheet(rowsRes);
XLSX.utils.book_append_sheet(wb,ws3,'Resumen');
XLSX.writeFile(wb,'Conciliacion_'+banco+'_'+periodo+'.xlsx');
if(toast$)toast$('✓ Excel descargado');
};

