function ReclasificadorCuentas({ session, toast$ }) {
const [ctaOrigen, setCtaOrigen] = useState('');
const [ctaDestino, setCtaDestino] = useState('');
const [fechaIni, setFechaIni] = useState('');
const [fechaFin, setFechaFin] = useState('');
const [preview, setPreview] = useState(null);
const [loading, setLoading] = useState(false);
const [ejecutando, setEjecutando] = useState(false);
const [f4Open, setF4Open] = useState(null);
const [f4Q, setF4Q] = useState('');
const [pucList, setPucList] = useState([]);
useEffect(()=>{
  Promise.all([db.getRenombres(session.empresaId),db.getAuxiliares(session.empresaId)]).then(([rens,auxs])=>{
    const mapa={};
    PUC_BASE.forEach(([c,n])=>{mapa[String(c)]=n;});
    if(Array.isArray(rens)) { rens.forEach(r=>{if(r.codigo&&r.nombre)mapa[String(r.codigo)]=r.nombre;}); }
    else if(rens&&typeof rens==='object') { Object.assign(mapa, rens); }
    (auxs||[]).forEach(a=>{if(a.c&&a.n)mapa[String(a.c)]=a.n;});
    setPucList(Object.entries(mapa).filter(([c])=>String(c).length>=4).sort((a,b)=>String(a[0]).localeCompare(String(b[0]))));
  });
},[]);
const pucFilt = pucList.filter(([c,n])=>
  !f4Q || c.includes(f4Q) || n.toLowerCase().includes(f4Q.toLowerCase())
).slice(0,40);
const lbl = {fontSize:'0.7rem',fontWeight:700,textTransform:'uppercase',letterSpacing:'0.8px',color:'rgba(255,255,255,0.5)',marginBottom:4,display:'block'};
const inp = {width:'100%',padding:'8px 12px',background:'rgba(255,255,255,0.05)',border:'1px solid rgba(255,255,255,0.12)',borderRadius:8,color:'#e8eaf0',fontSize:'0.83rem',outline:'none'};
const CampoCuenta = ({label, val, setVal}) => (
<div style={{position:'relative'}}>
<label style={lbl}>{label}</label>
<input value={val} onChange={e=>{setVal(e.target.value);setF4Q(e.target.value);setF4Open(label);}}
onFocus={()=>{setF4Open(label);setF4Q(val);}} onBlur={()=>setTimeout(()=>setF4Open(null),200)}
placeholder="Código o nombre..." style={inp}/>
{f4Open===label&&f4Q.length>=1&&(
<div style={{position:'absolute',top:'100%',left:0,right:0,background:'#1e2538',border:'1px solid rgba(255,255,255,0.12)',borderRadius:8,zIndex:300,maxHeight:200,overflowY:'auto',boxShadow:'0 8px 24px rgba(0,0,0,0.5)'}}>
{pucFilt.map(([c,n])=>(
<div key={c} onMouseDown={()=>{setVal(c);setF4Open(null);setF4Q('');}} style={{padding:'7px 12px',cursor:'pointer',display:'flex',justifyContent:'space-between',borderBottom:'1px solid rgba(255,255,255,0.04)'}} onMouseEnter={e=>e.currentTarget.style.background='#263050'} onMouseLeave={e=>e.currentTarget.style.background='transparent'}>
<span style={{fontSize:'0.77rem',color:'#e8eaf0'}}>{n}</span>
<span style={{fontSize:'0.72rem',fontFamily:'monospace',color:'#60a5fa'}}>{c}</span>
</div>
))}
</div>
)}
</div>
);
const buscarPreview = async () => {
if(!ctaOrigen||!ctaDestino||!fechaIni||!fechaFin){toast$('Complete todos los campos',false);return;}
if(ctaOrigen===ctaDestino){toast$('Origen y destino deben ser diferentes',false);return;}
setLoading(true);
const comps = await db.getComprobantes(session.empresaId);
let total = 0;
comps.filter(c=>c.fecha>=fechaIni&&c.fecha<=fechaFin).forEach(c=>{
const dets = c.detalles?JSON.parse(c.detalles):[];
dets.forEach(d=>{if(d.cuenta===ctaOrigen)total++;});
});
setPreview({total,ctaOrigen,ctaDestino,fechaIni,fechaFin});
setLoading(false);
if(total===0) toast$('No se encontraron movimientos con esa cuenta en el período',false);
};
const ejecutarReclasificacion = async () => {
if(!preview||preview.total===0) return;
if(!confirm(`¿Confirma reclasificar ${preview.total} movimientos de ${ctaOrigen} → ${ctaDestino}?`)) return;
setEjecutando(true);
const comps = await db.getComprobantes(session.empresaId);
let actualizados = 0;
for(const c of comps.filter(c=>c.fecha>=fechaIni&&c.fecha<=fechaFin)){
  const dets = c.detalles?JSON.parse(c.detalles):[];
  let cambio = false;
  const nuevos = dets.map(d=>{
    if(d.cuenta===ctaOrigen){cambio=true;return {...d,cuenta:ctaDestino};}
    return d;
  });
  if(cambio){
    await supabaseClient.from('comprobantes').update({detalles:JSON.stringify(nuevos)}).eq('id',c.id);
    actualizados++;
  }
}
setEjecutando(false);
setPreview(null);
toast$(`✓ ${preview.total} movimientos reclasificados en ${actualizados} comprobantes`);
};
return(
<div style={{background:'#171d2e',borderRadius:14,border:'1px solid rgba(255,255,255,0.08)',overflow:'hidden'}}>
<div style={{background:'linear-gradient(135deg,#0f1f3d,#1a3160)',padding:'14px 26px'}}>
<span style={{fontFamily:"'Playfair Display',serif",color:'#fff',fontSize:'1.05rem'}}>🔄 Reclasificador de Cuentas</span>
<div style={{fontSize:'0.72rem',color:'rgba(255,255,255,0.4)',marginTop:2}}>Cambia masivamente una cuenta contable en todos los comprobantes de un período</div>
</div>
<div style={{padding:20,display:'flex',flexDirection:'column',gap:14}}>
<div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:12}}>
<CampoCuenta label="Cuenta Origen (incorrecta)" val={ctaOrigen} setVal={setCtaOrigen}/>
<CampoCuenta label="Cuenta Destino (correcta)" val={ctaDestino} setVal={setCtaDestino}/>
<div><label style={lbl}>Fecha Inicial</label><input type="date" value={fechaIni} onChange={e=>setFechaIni(e.target.value)} style={inp}/></div>
<div><label style={lbl}>Fecha Final</label><input type="date" value={fechaFin} onChange={e=>setFechaFin(e.target.value)} style={inp}/></div>
</div>
<div style={{display:'flex',gap:10,alignItems:'center'}}>
<button onClick={buscarPreview} disabled={loading} style={{padding:'9px 20px',background:'rgba(79,142,247,0.15)',border:'1px solid rgba(79,142,247,0.3)',borderRadius:8,color:'#4f8ef7',cursor:'pointer',fontWeight:700,fontSize:'0.82rem'}}>
{loading?'Buscando...':'🔍 Buscar movimientos'}
</button>
{preview&&preview.total>0&&(
<button onClick={ejecutarReclasificacion} disabled={ejecutando} style={{padding:'9px 20px',background:'rgba(248,113,113,0.15)',border:'1px solid rgba(248,113,113,0.3)',borderRadius:8,color:'#f87171',cursor:'pointer',fontWeight:700,fontSize:'0.82rem'}}>
{ejecutando?'Ejecutando...':'⚡ Ejecutar reclasificación'}
</button>
)}
</div>
{preview&&(
<div style={{background:preview.total>0?'rgba(201,168,76,0.08)':'rgba(248,113,113,0.08)',border:`1px solid ${preview.total>0?'rgba(201,168,76,0.3)':'rgba(248,113,113,0.3)'}`,borderRadius:8,padding:'12px 16px',fontSize:'0.83rem'}}>
{preview.total>0?(
<><span style={{color:'#c9a84c',fontWeight:700}}>⚠ Vista previa:</span> Se reclasificarán <strong style={{color:'#fff'}}>{preview.total} movimientos</strong> de la cuenta <span style={{fontFamily:'monospace',color:'#60a5fa'}}>{ctaOrigen}</span> → <span style={{fontFamily:'monospace',color:'#4ade80'}}>{ctaDestino}</span> entre {fechaIni} y {fechaFin}</>
):(
<span style={{color:'#f87171'}}>No se encontraron movimientos con la cuenta {ctaOrigen} en el período seleccionado.</span>
)}
</div>
)}
</div>
</div>
);
}
